import assert from 'node:assert/strict';
import { writeFileSync, readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
const repo='/Users/aantich/dev/oneringai';
const require=createRequire(repo+'/package.json');
const lib=process.env.REVIEW_SOURCE ? (require('tsx/cjs'),require(repo+'/src/index.ts')) : await import(repo+'/dist/index.js');
const { AgentContextNextGen,InMemoryEvidenceStorage,FileContextStorage,Agent,Connector,Vendor }=lib;
const scope={ownerId:'alice',namespace:'second-review'};
const raw={id:'ONLY_COPY_731',detail:'exact source observation '.repeat(1200)};
const results={mode:process.env.REVIEW_SOURCE?'source':'built-public'};
function tool(name='probe',execute=async()=>raw,blocking=true){return {definition:{type:'function',blocking,function:{name,parameters:{type:'object',properties:{}}}},execute,output:{effect:'write',summarize:()=> 'stored source'}}}
function ctx(storage,sessions){return AgentContextNextGen.create({model:'gpt-4o-mini',agentId:'review',userId:'alice',storage:sessions,features:{workingMemory:false,inContextMemory:false,evidence:true},plugins:{evidence:{storage}}});}
function pair(c,r,withOutcome=true){c.addUserMessage('query');c.addAssistantResponse([{type:'message',role:'assistant',content:[{type:'tool_use',id:'call',name:'probe',arguments:'{}'}]}]);c.addToolResults([{tool_use_id:'call',content:r.result,state:'completed',evidence:r.evidence,...withOutcome?{outcome:r.outcome}:{}}]);}
async function missingOutcome(){
 for(const withOutcome of [false,true]){const store=new InMemoryEvidenceStorage({scope});store.put=async()=>{throw Error('offline')};const c=ctx(store);try{c.tools.register(tool());const r=await c.tools.executeWithOutcome('probe',{}, {callId:'call'});pair(c,r,withOutcome);const before=JSON.stringify(c.getCurrentInput());c.addAssistantResponse([]);let error,rolled;try{rolled=await c.rollover({preserveRecentTurns:0,summarize:async()=> 'discarded exact source'});}catch(e){error=e.message}results[withOutcome?'fullReportControl':'deliveryWithoutOutcome']={storage:r.evidence.status,metadataPresent:before.includes('storage_failed'),rolled:rolled?.performed??false,error,rawAfter:JSON.stringify(c.getConversation()).includes(raw.detail)};}finally{c.destroy()}}
 assert.equal(results.deliveryWithoutOutcome.rolled,true);assert.equal(results.deliveryWithoutOutcome.rawAfter,false);assert.match(results.fullReportControl.error,/unacknowledged/);
}
async function savePending(){
 const directory=await mkdtemp(join(tmpdir(),'oneringai-review-save-'));let saved;const sessions=new FileContextStorage({agentId:'review-save',baseDirectory:directory});const store=new InMemoryEvidenceStorage({scope});store.put=async()=>{throw Error('offline')};let calls=0,executions=0;
 const provider={name:'fixture',capabilities:{text:true},generate:async()=>{calls++;if(calls>1)throw Error('controlled provider unavailable');return response([{type:'tool_use',id:'call',name:'probe',arguments:'{}'}]);},getModelCapabilities:()=>({supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:128000,maxInputTokens:128000,maxOutputTokens:1024}),validateConfig:async()=>true,listModels:async()=>[],destroy(){}};
 Connector.create({name:'review-save',vendor:Vendor.OpenAI,auth:{type:'none'},options:{provider}});
 const create=()=>Agent.create({connector:'review-save',model:'gpt-4o-mini',userId:'alice',tools:[tool('probe',async()=>{executions++;return raw})],maxIterations:3,emptyResponseRetry:{enabled:false},context:{model:'gpt-4o-mini',storage:sessions,features:{workingMemory:false,inContextMemory:false,evidence:true},plugins:{evidence:{storage:store}}}});
 const agent=create(),restored=create();try{let error;try{await agent.run('write once')}catch(e){error=e.message}const pendingHasRaw=JSON.stringify(agent.context.getCurrentInput()).includes(raw.detail);await agent.saveSession('recovery');saved=(await sessions.load('recovery')).state;await restored.loadSession('recovery');results.pendingSave={backend:'FileContextStorage',error,calls,executions,pendingHasRaw,savedHasRaw:JSON.stringify(saved).includes(raw.detail),restoredHasRaw:JSON.stringify([...restored.context.getConversation(),...restored.context.getCurrentInput()]).includes(raw.detail),storedRecords:(await store.list()).entries.length};assert.match(error,/controlled provider unavailable/);assert.equal(executions,1);assert.equal(pendingHasRaw,true);assert.equal(results.pendingSave.savedHasRaw,false);assert.equal(results.pendingSave.restoredHasRaw,false);}finally{agent.destroy();restored.destroy();Connector.remove('review-save');await rm(directory,{recursive:true,force:true})}
}
function response(content){return {id:'r',object:'response',model:'gpt-4o-mini',created_at:1,status:'completed',output_text:content[0]?.type==='output_text'?'done':'',output:[{type:'message',role:'assistant',content}],usage:{input_tokens:10,output_tokens:5,total_tokens:15}};}
async function asyncOverwrite(){
 const packets=[];let executions=0;let complete;
 const ready=new Promise(resolve=>complete=resolve);
 const store=new InMemoryEvidenceStorage({scope});const put=store.put.bind(store);store.put=async r=>{if(r.source.toolName==='probe')throw Error('offline');return put(r)};
 const provider={name:'fixture',capabilities:{text:true},generate:async options=>{packets.push(structuredClone(options));return response(packets.length===1?[{type:'tool_use',id:'background-call',name:'background',arguments:'{}'},{type:'tool_use',id:'call',name:'probe',arguments:'{}'}]:[{type:'output_text',text:'done'}]);},getModelCapabilities:()=>({supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:128000,maxInputTokens:128000,maxOutputTokens:1024}),validateConfig:async()=>true,listModels:async()=>[],destroy(){}};
 Connector.create({name:'review-second',vendor:Vendor.OpenAI,auth:{type:'none'},options:{provider}});
 const agent=Agent.create({connector:'review-second',model:'gpt-4o-mini',userId:'alice',tools:[tool('background',async()=>({ready:true}),false),tool('probe',async()=>{executions++;await ready;return raw})],maxIterations:3,emptyResponseRetry:{enabled:false},asyncTools:{autoContinue:false},context:{model:'gpt-4o-mini',features:{workingMemory:false,inContextMemory:false,evidence:true},plugins:{evidence:{storage:store}}}});
 let beforeInjectionHasRaw=false;agent.on('async:tool:complete',()=>complete());agent.on('iteration:complete',()=>{beforeInjectionHasRaw ||= JSON.stringify(agent.context.getCurrentInput()).includes(raw.detail)});
 try{let error;try{await agent.run('run both')}catch(e){error=e.message}const all=JSON.stringify([...agent.context.getConversation(),...agent.context.getCurrentInput()]);results.asyncOverwritesUnacknowledged={error,executions,providerCalls:packets.length,beforeInjectionHasRaw,nextPacketHasRaw:packets[1]?JSON.stringify(packets[1].input).includes(raw.detail):false,retainedHasRaw:all.includes(raw.detail),storedProbeRecords:(await store.list()).entries.filter(e=>e.toolName==='probe').length,retainedCalls:all.includes('"id":"call"')};assert.equal(executions,1);assert.equal(results.asyncOverwritesUnacknowledged.retainedHasRaw,false);assert.equal(results.asyncOverwritesUnacknowledged.storedProbeRecords,0);}finally{agent.destroy();Connector.remove('review-second')}
}
await missingOutcome();await savePending();await asyncOverwrite();
writeFileSync('/tmp/oneringai-stage03-second-review-repro'+(process.env.REVIEW_SOURCE?'-source':'')+'.json',JSON.stringify(results,null,2)+'\n');console.log(JSON.stringify(results,null,2));
